/// Given a non-empty slice `a` of integers and two indices `s` and `e` such that
/// 0 <= s < e <= a.len(), returns some index `m` in [s, e) at which `a[m]`
/// is minimal over that half-open interval.
pub fn find_min_index(a: &[i32], s: usize, e: usize) -> usize {
    // Precondition (assumed to hold): 0 <= s < e <= a.len()
    let mut min_i = s;
    for i in (s + 1)..e {
        if a[i] < a[min_i] {
            min_i = i;
        }
    }
    min_i
}

